class Shared {
    private int value;

    synchronized void write(int v) { value = v; }

    int read() { return value; }          // NOT synchronized
}

class Config {
    int retries;
    Config() { retries = 3; }
}

static Config config;          // plain field
static int hits = 0;           // plain field

// Thread A
config = new Config();
hits++;

// Thread B (and several other threads also run hits++)
while (config == null) { }
System.out.println(config.retries + " " + hits);

